    private function one(PDO $pdo, string $sql, array $args = []): array
    {
        $q = $pdo->prepare($sql); $q->execute($args); $row = $q->fetch(PDO::FETCH_ASSOC); return is_array($row) ? $row : [];
    }
    private function optionalOne(PDO $pdo, string $sql, array $args = []): array
    {
        try { return $this->one($pdo,$sql,$args); } catch (\Throwable $e) { error_log('P2K Green freshness optional query: '.$e->getMessage()); return []; }
    }
    private static function epoch(mixed $value): ?int
    {
        $raw=trim((string)($value??'')); if($raw==='')return null; $time=strtotime($raw.(preg_match('/(?:Z|[+-]\d\d:?\d\d)$/',$raw)?'':' UTC')); return $time===false?null:$time;
    }
    private static function ageSeconds(mixed $value): ?int { $time=self::epoch($value); return $time===null?null:max(0,time()-$time); }
    private static function percent(int $good,int $total): float { return $total>0?round(100*max(0,min($total,$good))/$total,1):100.0; }
    private function greenApp(): array
