        $root=dirname(__DIR__,3);$path=$root.'/data/tournaments/archive.json';$data=null;$source='none';
        if(is_file($path)){$decoded=json_decode((string)@file_get_contents($path),true);if(is_array($decoded)){$data=$decoded;$source='archive';}}
        if(!is_array($data)){$backups=glob(dirname($path).'/backups/archive-*.json')?:[];rsort($backups,SORT_STRING);foreach($backups as $backup){$decoded=json_decode((string)@file_get_contents($backup),true);if(is_array($decoded)&&(!empty($decoded['tournaments'])||!empty($decoded['reinitializedAt']))){$data=$decoded;$source='backup';break;}}}
        if(!is_array($data))return ['observed_at'=>null,'age_seconds'=>null,'status_checked_at'=>null,'status_age_seconds'=>null,'tournament_count'=>null,'source'=>$source,'target_seconds'=>600];
        $last=$data['lastStatusRefresh']??null;$observed=is_array($last)?($last['at']??null):(is_string($last)?$last:null);$status=$data['scanState']['lastStatusCheckAt']??(is_array($last)?($last['statusCheckedAt']??null):null);$observed??=$data['scanState']['lastSync']??($data['generatedAt']??null);$status??=$observed;if($observed===null&&is_file($path))$observed=gmdate('Y-m-d H:i:s',(int)filemtime($path));
        return ['observed_at'=>$observed,'age_seconds'=>self::ageSeconds($observed),'status_checked_at'=>$status,'status_age_seconds'=>self::ageSeconds($status),'tournament_count'=>is_array($data['tournaments']??null)?count($data['tournaments']):null,'source'=>$source,'target_seconds'=>600];
    }

