        $players=$this->optionalOne($this->core,"SELECT COUNT(*) known_players,COALESCE(SUM(current_member=1),0) current_members,COALESCE(SUM(current_member=1 AND profile_checked_at IS NOT NULL),0) profile_checked,COALESCE(SUM(current_member=1 AND profile_checked_at IS NULL),0) profile_missing,COALESCE(SUM(current_member=1 AND stats_checked_at IS NOT NULL),0) stats_checked,COALESCE(SUM(current_member=1 AND stats_checked_at IS NULL),0) stats_never,COALESCE(SUM(current_member=1 AND (stats_checked_at IS NULL OR stats_checked_at<?)),0) stats_due,COALESCE(SUM(current_member=1 AND stats_checked_at>=?),0) stats_fresh,COALESCE(SUM(current_member=1 AND (daily_rating IS NOT NULL OR chess960_rating IS NOT NULL)),0) rated,COALESCE(SUM(current_member=1 AND (daily_rating IS NOT NULL OR chess960_rating IS NOT NULL) AND stats_checked_at>=?),0) fresh_ratings,COALESCE(SUM(current_member=1 AND avatar_url IS NOT NULL AND avatar_url<>''),0) avatars,MIN(CASE WHEN current_member=1 AND stats_checked_at IS NOT NULL THEN stats_checked_at END) oldest_stats_at,MAX(CASE WHEN current_member=1 THEN last_seen_roster_at END) newest_roster_seen_at FROM p2k_g_players",[$statsCutoff,$statsCutoff,$statsCutoff]);
