        $quick=['total'=>0,'completed'=>0,'pending'=>0,'deferred_transient'=>0];$cycleNo=(int)($state['cycle_no']??0);if($cycleNo>0)$quick=$this->optionalOne($this->core,"SELECT COUNT(*) total,COALESCE(SUM(status='completed'),0) completed,COALESCE(SUM(status='pending'),0) pending,COALESCE(SUM(status='completed' AND requeued_for_next=1 AND terminal_http_status IS NOT NULL AND terminal_http_status NOT IN (200,204,404,410)),0) deferred_transient FROM p2k_g_quick_board_cycle_items WHERE cycle_no=?",[$cycleNo])+$quick;
